package rules

import "testing"

// Cases ported verbatim from php-cs-fixer StatementIndentationFixerTest
// (tests/Fixer/Whitespace/StatementIndentationFixerTest.php). blink does not
// yet match every case; the ones it misses are gated behind
// stmtIndentKnownFailures so this port can land without fixing the rule. A
// listed case that starts passing fails the test so the list gets pruned.
// The single tab-indent case cannot be expressed through blink's test harness
// (no WhitespacesFixerConfig), so it is a permanent known gap.
func TestStatementIndentationPhpCsFixerCases(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name     string
		cfg      map[string]any
		input    string
		expected string
	}{
		{"no brace block", nil, "<?php\n  foo();\n       bar();", "<?php\nfoo();\nbar();"},
		{"simple", nil, "<?php\nif ($foo) {\n  foo();\n       bar();\n }", "<?php\nif ($foo) {\n    foo();\n    bar();\n}"},
		{"braces on same line as code", nil, "<?php\nif ($foo) {\n foo();\n       if ($bar) { bar(); }\n  }", "<?php\nif ($foo) {\n    foo();\n    if ($bar) { bar(); }\n}"},
		{"with several closing braces on same line", nil, "<?php\nif ($foo) { foo();\n if ($bar) { bar();\n  if ($baz) { baz(); }}\n   foo();\n   }\n  foo();", "<?php\nif ($foo) { foo();\n    if ($bar) { bar();\n        if ($baz) { baz(); }}\n    foo();\n}\nfoo();"},
		{"with meaningful content on closing line", nil, "<?php\nif ($foo) {\n    foo(); }\n    foo();", "<?php\nif ($foo) {\n    foo(); }\nfoo();"},
		{"with several opening braces on same line", nil, "<?php\nif ($foo) { if ($foo) { foo();\n  if ($bar) { if ($bar) { bar(); }\n   baz();\n  }\n  }\n   baz();\n   }\n  baz();", "<?php\nif ($foo) { if ($foo) { foo();\n    if ($bar) { if ($bar) { bar(); }\n        baz();\n    }\n}\n    baz();\n}\nbaz();"},
		{"function definition arguments", nil, "<?php\n   function foo(\n     $bar,\n      $baz\n ) {\n  }", "<?php\nfunction foo(\n    $bar,\n    $baz\n) {\n}"},
		{"anonymous function definition arguments", nil, "<?php\n   $foo = function(\n     $bar,\n      $baz\n ) {\n  };", "<?php\n$foo = function(\n    $bar,\n    $baz\n) {\n};"},
		{"interface method definition arguments", nil, "<?php\ninterface Foo {\n   public function foo(\n     $bar,\n      $baz\n );\n }", "<?php\ninterface Foo {\n    public function foo(\n        $bar,\n        $baz\n    );\n}"},
		{"class method definition arguments", nil, "<?php\nclass Foo {\n   public function foo(\n     $bar,\n      $baz\n ) {\n  }\n }", "<?php\nclass Foo {\n    public function foo(\n        $bar,\n        $baz\n    ) {\n    }\n}"},
		{"multiple class methods with many permutations of visibility modifiers", nil, "<?php\nabstract class Test {\n                      final protected function test_final_protected() {}\n                 static private function test_static_private() {}\n                    private function test_private() {}\n             private static function test_private_static() {}\n        abstract public static function test_abstract_public_static();\n                 abstract static public function test_abstract_static_public();\nabstract public function test_abstract_public();\nprotected abstract function test_protected_abstract();\n       public abstract function test_public_abstract();\n       final static protected function test_final_static_protected() {}\n                     final private static function test_final_private_static() {}\n           public final function test_public_final() {}\n                      final private function test_final_private() {}\n            static final public function test_static_final_public() {}\n           protected abstract static function test_protected_abstract_static();\n                 public static abstract function test_public_static_abstract();\n                       protected static abstract function test_protected_static_abstract();\n                      static final function test_static_final() {}\n                final static private function test_final_static_private() {}\n             static protected abstract function test_static_protected_abstract();\n public abstract static function test_public_abstract_static();\n     static final protected function test_static_final_protected() {}\n      final public static function test_final_public_static() {}\n     static final private function test_static_final_private() {}\n  abstract protected function test_abstract_protected();\n      abstract static protected function test_abstract_static_protected();\n                    private static final function test_private_static_final() {}\n               final static function test_final_static() {}\n           protected static function test_protected_static() {}\n        protected function test_protected() {}\n   public static function test_public_static() {}\n         final function test_final() {}\n                   abstract protected static function test_abstract_protected_static();\n     static protected function test_static_protected() {}\n      static abstract function test_static_abstract();\n        static abstract protected function test_static_abstract_protected();\n               protected final static function test_protected_final_static() {}\nstatic public final function test_static_public_final() {}\n       public final static function test_public_final_static() {}\n                    abstract static function test_abstract_static();\n                    public static final function test_public_static_final() {}\n   static function test_static() {}\n          abstract function test_abstract();\n                      static protected final function test_static_protected_final() {}\n                       static private final function test_static_private_final() {}\n        private final function test_private_final() {}\n                  static public abstract function test_static_public_abstract();\n                     protected static final function test_protected_static_final() {}\n                  final protected static function test_final_protected_static() {}\n               final static public function test_final_static_public() {}\n                  static public function test_static_public() {}\n                    function test_() {}\n                       static abstract public function test_static_abstract_public();\n          final public function test_final_public() {}\n                 private final static function test_private_final_static() {}\n                protected final function test_protected_final() {}\n  public function test_public() {}\n}", "<?php\nabstract class Test {\n    final protected function test_final_protected() {}\n    static private function test_static_private() {}\n    private function test_private() {}\n    private static function test_private_static() {}\n    abstract public static function test_abstract_public_static();\n    abstract static public function test_abstract_static_public();\n    abstract public function test_abstract_public();\n    protected abstract function test_protected_abstract();\n    public abstract function test_public_abstract();\n    final static protected function test_final_static_protected() {}\n    final private static function test_final_private_static() {}\n    public final function test_public_final() {}\n    final private function test_final_private() {}\n    static final public function test_static_final_public() {}\n    protected abstract static function test_protected_abstract_static();\n    public static abstract function test_public_static_abstract();\n    protected static abstract function test_protected_static_abstract();\n    static final function test_static_final() {}\n    final static private function test_final_static_private() {}\n    static protected abstract function test_static_protected_abstract();\n    public abstract static function test_public_abstract_static();\n    static final protected function test_static_final_protected() {}\n    final public static function test_final_public_static() {}\n    static final private function test_static_final_private() {}\n    abstract protected function test_abstract_protected();\n    abstract static protected function test_abstract_static_protected();\n    private static final function test_private_static_final() {}\n    final static function test_final_static() {}\n    protected static function test_protected_static() {}\n    protected function test_protected() {}\n    public static function test_public_static() {}\n    final function test_final() {}\n    abstract protected static function test_abstract_protected_static();\n    static protected function test_static_protected() {}\n    static abstract function test_static_abstract();\n    static abstract protected function test_static_abstract_protected();\n    protected final static function test_protected_final_static() {}\n    static public final function test_static_public_final() {}\n    public final static function test_public_final_static() {}\n    abstract static function test_abstract_static();\n    public static final function test_public_static_final() {}\n    static function test_static() {}\n    abstract function test_abstract();\n    static protected final function test_static_protected_final() {}\n    static private final function test_static_private_final() {}\n    private final function test_private_final() {}\n    static public abstract function test_static_public_abstract();\n    protected static final function test_protected_static_final() {}\n    final protected static function test_final_protected_static() {}\n    final static public function test_final_static_public() {}\n    static public function test_static_public() {}\n    function test_() {}\n    static abstract public function test_static_abstract_public();\n    final public function test_final_public() {}\n    private final static function test_private_final_static() {}\n    protected final function test_protected_final() {}\n    public function test_public() {}\n}"},
		{"trait method definition arguments", nil, "<?php\ntrait Foo {\n   public function foo(\n     $bar,\n      $baz\n ) {\n  }\n }", "<?php\ntrait Foo {\n    public function foo(\n        $bar,\n        $baz\n    ) {\n    }\n}"},
		{"function call arguments", nil, "<?php\nfoo(\n  $bar,\n   $baz\n    );", "<?php\nfoo(\n    $bar,\n    $baz\n);"},
		{"variable function call arguments", nil, "<?php\n$foo(\n  $bar,\n   $baz\n    );", "<?php\n$foo(\n    $bar,\n    $baz\n);"},
		{"chained method calls", nil, "<?php\n  if ($foo) {\n         $foo\n                    ->bar()\n                      ->baz()\n                        ;\n      }", "<?php\nif ($foo) {\n    $foo\n               ->bar()\n                 ->baz()\n    ;\n}"},
		{"nested arrays (long syntax)", nil, "<?php\n  if ($foo) {\n         $foo = array(\n                  $foo,\n                    $bar\n                        ->bar()\n                       ,\n                        array($baz)\n                 )\n                 ;\n      }", "<?php\nif ($foo) {\n    $foo = array(\n             $foo,\n               $bar\n                   ->bar()\n                  ,\n                   array($baz)\n            )\n    ;\n}"},
		{"nested arrays (short syntax)", nil, "<?php\n  if ($foo) {\n         $foo = [\n                  $foo,\n                    $bar\n                        ->bar()\n                       ,\n                        [$baz]\n                 ]\n                 ;\n      }", "<?php\nif ($foo) {\n    $foo = [\n             $foo,\n               $bar\n                   ->bar()\n                  ,\n                   [$baz]\n            ]\n    ;\n}"},
		{"array (long syntax) with function call", nil, "<?php\n  if ($foo) {\n         $foo = array(\n                  foo(\n                   $bar,\n                     $baz\n                     )\n                  )\n                 ;\n      }", "<?php\nif ($foo) {\n    $foo = array(\n             foo(\n                 $bar,\n                 $baz\n             )\n             )\n    ;\n}"},
		{"array (short syntax) with function call", nil, "<?php\n  if ($foo) {\n         $foo = [\n                  foo(\n                   $bar,\n                     $baz\n                     )\n                  ]\n                 ;\n      }", "<?php\nif ($foo) {\n    $foo = [\n             foo(\n                 $bar,\n                 $baz\n             )\n             ]\n    ;\n}"},
		{"array (long syntax) with class instantiation", nil, "<?php\n  if ($foo) {\n         $foo = array(\n                  new Foo(\n                   $bar,\n                     $baz\n                     )\n                  )\n                 ;\n      }", "<?php\nif ($foo) {\n    $foo = array(\n             new Foo(\n                 $bar,\n                 $baz\n             )\n             )\n    ;\n}"},
		{"array (short syntax) with class instantiation", nil, "<?php\n  if ($foo) {\n         $foo = [\n                  new Foo(\n                   $bar,\n                     $baz\n                     )\n                  ]\n                 ;\n      }", "<?php\nif ($foo) {\n    $foo = [\n             new Foo(\n                 $bar,\n                 $baz\n             )\n             ]\n    ;\n}"},
		{"implements list", nil, "<?php\n  class Foo implements\n   Bar,\n    Baz\n     {}", "<?php\nclass Foo implements\n    Bar,\n    Baz\n{}"},
		{"extends list", nil, "<?php\n  interface Foo extends\n   Bar,\n    Baz\n     {}", "<?php\ninterface Foo extends\n    Bar,\n    Baz\n{}"},
		{"use list", nil, "<?php\n  class Foo {\n       use Bar,\n              Baz;\n }", "<?php\nclass Foo {\n    use Bar,\n        Baz;\n}"},
		{"chained method call with argument", nil, "<?php\n$foo\n ->bar(\n  $baz\n );", "<?php\n$foo\n ->bar(\n     $baz\n );"},
		{"argument separator on its own line", nil, "<?php\nfoo(\n 1\n,\n 2\n);", "<?php\nfoo(\n    1\n    ,\n    2\n);"},
		{"statement end on its own line", nil, "<?php\nif (true) {\n  $foo =\n       $a\n           && $b\n             ;\n}", "<?php\nif (true) {\n    $foo =\n         $a\n             && $b\n    ;\n}"},
		{"multiline control structure conditions", nil, "<?php\nif ($a\n       && $b) {\n     foo();\n }", "<?php\nif ($a\n       && $b) {\n    foo();\n}"},
		{"switch", nil, "<?php\nswitch ($foo) {\n  case 1:\n     echo \"foo\";\n  break;\n  case 2:\n     echo \"bar\";\n break;\n  case 3:\n   default:\n    echo \"baz\";\n}", "<?php\nswitch ($foo) {\n    case 1:\n        echo \"foo\";\n        break;\n    case 2:\n        echo \"bar\";\n        break;\n    case 3:\n    default:\n        echo \"baz\";\n}"},
		{"array (long syntax) with anonymous class", nil, "<?php\n  if ($foo) {\n         $foo = array(\n                  new class (\n                   $bar,\n                     $baz\n                      ) {\n                        private $foo;\n\n                       public function foo(\n                       $foo\n                        ) {\n                             return $foo;\n                            }\n                     }\n                  )\n                 ;\n      }", "<?php\nif ($foo) {\n    $foo = array(\n             new class (\n                 $bar,\n                 $baz\n             ) {\n                 private $foo;\n\n                 public function foo(\n                     $foo\n                 ) {\n                     return $foo;\n                 }\n             }\n             )\n    ;\n}"},
		{"array (short syntax) with anonymous class", nil, "<?php\n  if ($foo) {\n         $foo = [\n                  new class (\n                   $bar,\n                     $baz\n                      ) {\n                        private $foo;\n\n                       public function foo(\n                       $foo\n                        ) {\n                             return $foo;\n                            }\n                     }\n                  ]\n                 ;\n      }", "<?php\nif ($foo) {\n    $foo = [\n             new class (\n                 $bar,\n                 $baz\n             ) {\n                 private $foo;\n\n                 public function foo(\n                     $foo\n                 ) {\n                     return $foo;\n                 }\n             }\n             ]\n    ;\n}"},
		{"expression function call arguments", nil, "<?php\n('foo')(\n  $bar,\n   $baz\n    );", "<?php\n('foo')(\n    $bar,\n    $baz\n);"},
		{"arrow function definition arguments", nil, "<?php\n   $foo = fn(\n     $bar,\n      $baz\n ) => null;", "<?php\n$foo = fn(\n    $bar,\n    $baz\n) => null;"},
		{"multiline list in foreach", nil, "<?php\nforeach ($array as [\n    \"foo\" => $foo,\n    \"bar\" => $bar,\n]) {\n}", "<?php\nforeach ($array as [\n    \"foo\" => $foo,\n    \"bar\" => $bar,\n]) {\n}"},
		{"switch case with control structure", nil, "<?php\nswitch ($foo) {\n    case true:\n    if ($bar) {\n      bar();\n    }\nreturn true;\n}", "<?php\nswitch ($foo) {\n    case true:\n        if ($bar) {\n            bar();\n        }\n        return true;\n}"},
		{"comment in method calls chain", nil, "<?php\n$foo\n    ->baz()\n    /* ->baz() */\n;", "<?php\n$foo\n    ->baz()\n    /* ->baz() */\n;"},
		{"multiple anonymous functions as function arguments", nil, "<?php\nfoo(function () {\n    bar();\n}, function () {\n    baz();\n});", "<?php\nfoo(function () {\n    bar();\n}, function () {\n    baz();\n});"},
		{"multiple anonymous functions as method arguments", nil, "<?php\n$this\n    ->bar(function ($a) {\n        echo $a;\n    }, function ($b) {\n        echo $b;\n    })\n;", "<?php\n$this\n    ->bar(function ($a) {\n        echo $a;\n    }, function ($b) {\n        echo $b;\n    })\n;"},
		{"semicolon on a newline inside a switch case without break statement", nil, "<?php\nswitch (true) {\n    case $foo:\n        $foo\n            ->baz()\n        ;\n}", "<?php\nswitch (true) {\n    case $foo:\n        $foo\n            ->baz()\n        ;\n}"},
		{"alternative syntax", nil, "<?php if (1): ?>\n    <div></div>\n<?php else: ?>\n    <?php if (2): ?>\n        <div></div>\n    <?php else: ?>\n        <div></div>\n    <?php endif; ?>\n<?php endif; ?>\n", "<?php if (1): ?>\n    <div></div>\n<?php else: ?>\n    <?php if (2): ?>\n        <div></div>\n    <?php else: ?>\n        <div></div>\n    <?php endif; ?>\n<?php endif; ?>\n"},
		{"trait import with conflict resolution", nil, "<?php\nclass Foo {\n    use Bar,\n      Baz {\n       Baz::baz insteadof Bar;\n       }\n}", "<?php\nclass Foo {\n    use Bar,\n        Baz {\n            Baz::baz insteadof Bar;\n        }\n}"},
		{"multiline class definition", nil, "<?php\nclass Foo\n  extends\n    BaseFoo\n   implements Bar,\n  Baz {\n    public function foo() {\n    }\n}", "<?php\nclass Foo\nextends\n    BaseFoo\nimplements Bar,\n    Baz {\n    public function foo() {\n    }\n}"},
		{"comment at end of switch case", nil, "<?php\nswitch ($foo) {\n    case 1:\n        // Nothing to do\n}", "<?php\nswitch ($foo) {\n    case 1:\n        // Nothing to do\n}"},
		{"comment at end of switch default", nil, "<?php\nswitch ($foo) {\n    case 1:\n        break;\n    case 2:\n        break;\n    default:\n        // Nothing to do\n}", "<?php\nswitch ($foo) {\n    case 1:\n        break;\n    case 2:\n        break;\n    default:\n        // Nothing to do\n}"},
		{"switch ending with empty case", nil, "<?php\nswitch ($foo) {\n    case 1:\n}", "<?php\nswitch ($foo) {\n    case 1:\n}"},
		{"switch ending with empty default", nil, "<?php\nswitch ($foo) {\n    default:\n}", "<?php\nswitch ($foo) {\n    default:\n}"},
		{"function ending with a comment and followed by a comma", nil, "<?php\nfoo(function () {\n    bar();\n    // comment\n}, );", "<?php\nfoo(function () {\n    bar();\n    // comment\n}, );"},
		{"multiline arguments starting with \"new\" keyword", nil, "<?php\n$result1 = foo(\n    new Bar1(),\n    1\n);\n$result2 = ($function)(\n    new Bar2(),\n    2\n);\n$result3 = (new Argument())(\n    new Bar3(),\n    3\n);", "<?php\n$result1 = foo(\n    new Bar1(),\n    1\n);\n$result2 = ($function)(\n    new Bar2(),\n    2\n);\n$result3 = (new Argument())(\n    new Bar3(),\n    3\n);"},
		{"if with only a comment and followed by else", nil, "<?php\nif (true) {\n// foo\n} else {\n        // bar\n}", "<?php\nif (true) {\n    // foo\n} else {\n    // bar\n}"},
		{"comment before else blocks WITHOUT stick_comment_to_next_continuous_control_statement", map[string]any{"stick_comment_to_next_continuous_control_statement": false}, "<?php\n        // foo\nif ($foo) {\n    echo \"foo\";\n        // bar\n} else {\n    $aaa = 1;\n}", "<?php\n// foo\nif ($foo) {\n    echo \"foo\";\n    // bar\n} else {\n    $aaa = 1;\n}"},
		{"comment before else blocks WITH stick_comment_to_next_continuous_control_statement", map[string]any{"stick_comment_to_next_continuous_control_statement": true}, "<?php\n        // foo\nif ($foo) {\n    echo \"foo\";\n        // bar\n} else {\n    $aaa = 1;\n}", "<?php\n// foo\nif ($foo) {\n    echo \"foo\";\n// bar\n} else {\n    $aaa = 1;\n}"},
		{"multiline comment in block - describing next block", map[string]any{"stick_comment_to_next_continuous_control_statement": true}, "<?php\nif (1) {\n    $b = \"a\";\n    // multiline comment line 1\n    // multiline comment line 2\n    // multiline comment line 3\n} else {\n    $c = \"b\";\n}", "<?php\nif (1) {\n    $b = \"a\";\n// multiline comment line 1\n// multiline comment line 2\n// multiline comment line 3\n} else {\n    $c = \"b\";\n}"},
		{"multiline comment in block - the only content in block", nil, "<?php\nif (1) {\n // multiline comment line 1\n  // multiline comment line 2\n// multiline comment line 3\n} else {\n    $c = \"b\";\n}", "<?php\nif (1) {\n    // multiline comment line 1\n    // multiline comment line 2\n    // multiline comment line 3\n} else {\n    $c = \"b\";\n}"},
		{"comment before elseif blocks", map[string]any{"stick_comment_to_next_continuous_control_statement": true}, "<?php\n    // foo\nif ($foo) {\n    echo \"foo\";\n    // bar\n} elseif(1) {\n    echo \"bar\";\n} elseif(2) {\n// do nothing\n} elseif(3) {\n    $aaa = 1;\n    // end comment in final block\n}", "<?php\n// foo\nif ($foo) {\n    echo \"foo\";\n// bar\n} elseif(1) {\n    echo \"bar\";\n} elseif(2) {\n    // do nothing\n} elseif(3) {\n    $aaa = 1;\n    // end comment in final block\n}"},
		{"comments at the end of if/elseif/else blocks", map[string]any{"stick_comment_to_next_continuous_control_statement": true}, "<?php\nif ($foo) {\n    echo \"foo\";\n    // foo\n} elseif ($bar) {\n    echo \"bar\";\n    // bar\n} else {\n    echo \"baz\";\n    // baz\n}", "<?php\nif ($foo) {\n    echo \"foo\";\n// foo\n} elseif ($bar) {\n    echo \"bar\";\n// bar\n} else {\n    echo \"baz\";\n    // baz\n}"},
		{"if-elseif-else without braces", nil, "<?php\nif ($foo)\nfoo();\nelseif ($bar)\n  bar();\nelse\n        baz();", "<?php\nif ($foo)\n    foo();\nelseif ($bar)\n    bar();\nelse\n    baz();"},
		{"for without braces", nil, "<?php\nfor (;;)\n  foo();", "<?php\nfor (;;)\n    foo();"},
		{"foreach without braces", nil, "<?php\nforeach ($foo as $bar)\n  foo();", "<?php\nforeach ($foo as $bar)\n    foo();"},
		{"while without braces", nil, "<?php\nwhile (true)\n  foo();", "<?php\nwhile (true)\n    foo();"},
		{"do-while without braces", nil, "<?php\ndo\n  foo();\n while (true);", "<?php\ndo\n    foo();\nwhile (true);"},
		{"nested control structures without braces", nil, "<?php\nif (true)\nif (true)\n if (true)\n    for ($i = 0; $i < 1; ++$i)\n  echo 1;\nelseif (true)\n  foreach ([] as $foo)\n   echo 2;\nelse if (true)\n  while (true)\n   echo 3;\n  else\n  do\n      echo 4;\n      while (true);\n    else\n     echo 5;", "<?php\nif (true)\n    if (true)\n        if (true)\n            for ($i = 0; $i < 1; ++$i)\n                echo 1;\n        elseif (true)\n            foreach ([] as $foo)\n                echo 2;\n        else if (true)\n            while (true)\n                echo 3;\n        else\n            do\n                echo 4;\n            while (true);\n    else\n        echo 5;"},
		{"mixex if-else with and without braces", nil, "<?php\nif (true)\n  if (true) {\n          if (true)\n               echo 1;\n  else\n        echo 2;\n   }\n else {\n    echo 3;\n }\n    else\n     echo 4;", "<?php\nif (true)\n    if (true) {\n        if (true)\n            echo 1;\n        else\n            echo 2;\n    }\n    else {\n        echo 3;\n    }\nelse\n    echo 4;"},
		{"empty if and else without braces", nil, "<?php\n  if (true) {\n   if (false);\n  elseif (false);\n else if (false);\nelse\necho 1;\n}", "<?php\nif (true) {\n    if (false);\n    elseif (false);\n    else if (false);\n    else\n        echo 1;\n}"},
		{"multiline class constant", nil, "<?php\nclass Foo\n{\n  const\n     FOO = 1;\n  const BAR\n  = 2;\n}", "<?php\nclass Foo\n{\n    const\n        FOO = 1;\n    const BAR\n        = 2;\n}"},
		{"multiline class constant with visibility", nil, "<?php\nclass Foo\n{\n  public const\n     FOO = 1;\n  protected const\n         BAR = 1;\n  private const\n                BAZ = 1;\n}", "<?php\nclass Foo\n{\n    public const\n        FOO = 1;\n    protected const\n        BAR = 1;\n    private const\n        BAZ = 1;\n}"},
		{"multiline comma-separated class constants", nil, "<?php\nclass Foo\n{\n  const\n     FOO = 1,\n      BAR = 2;\n}", "<?php\nclass Foo\n{\n    const\n        FOO = 1,\n        BAR = 2;\n}"},
		{"multiline class constant with array value", nil, "<?php\nclass Foo\n{\n  const\n     FOO = [\n               1\n                          ];\n}", "<?php\nclass Foo\n{\n    const\n        FOO = [\n                  1\n                             ];\n}"},
		{"multiline class constants with array key/value", nil, "<?php\nclass Foo\n{\n  const\n        READY = \"GO\",\n    FOO = [\n        \"foo\" => \"bar\",\n    ],\n        BAR = \"Foo\",\n      STOP = \"STOP\";\n}", "<?php\nclass Foo\n{\n    const\n        READY = \"GO\",\n        FOO = [\n            \"foo\" => \"bar\",\n        ],\n        BAR = \"Foo\",\n        STOP = \"STOP\";\n}"},
		{"multiline class constant with semicolon on next line", nil, "<?php\nclass Foo\n{\n  public const\n     FOO = 1\n      ;\n}", "<?php\nclass Foo\n{\n    public const\n        FOO = 1\n    ;\n}"},
		{"multiline class property", nil, "<?php\nclass Foo\n{\n  public\n     $foo;\n  protected\n         $bar;\n  private\n                $baz;\n}", "<?php\nclass Foo\n{\n    public\n        $foo;\n    protected\n        $bar;\n    private\n        $baz;\n}"},
		{"multiline class property with default value", nil, "<?php\nclass Foo\n{\n  public\n     $foo = 1;\n}", "<?php\nclass Foo\n{\n    public\n        $foo = 1;\n}"},
		{"multiline class typed property", nil, "<?php\nclass Foo\n{\n  public\n     int $foo;\n}", "<?php\nclass Foo\n{\n    public\n        int $foo;\n}"},
		{"multiline class static property", nil, "<?php\nclass Foo\n{\n  public static\n     $foo;\n  static public\n       $bar;\n}", "<?php\nclass Foo\n{\n    public static\n        $foo;\n    static public\n        $bar;\n}"},
		{"multiline comma-separated class properties", nil, "<?php\nclass Foo\n{\n  public\n     $foo,\n      $bar;\n}", "<?php\nclass Foo\n{\n    public\n        $foo,\n        $bar;\n}"},
		{"multiline class property with array value", nil, "<?php\nclass Foo\n{\n  public\n     $foo = [\n               1\n                          ];\n}", "<?php\nclass Foo\n{\n    public\n        $foo = [\n                  1\n                             ];\n}"},
		{"multiline class property with semicolon on next line", nil, "<?php\nclass Foo\n{\n  public\n     $foo\n      ;\n}", "<?php\nclass Foo\n{\n    public\n        $foo\n    ;\n}"},
		{"multiline class property with var", nil, "<?php\nclass Foo\n{\n  var\n     $foo;\n}", "<?php\nclass Foo\n{\n    var\n        $foo;\n}"},
		{"property with multiline array containing explicit keys", nil, "<?php\nclass Foo\n{\n    private $foo = [\n        'a' => 1,\n        'b' => 2,\n    ];\n}", "<?php\nclass Foo\n{\n    private $foo = [\n        'a' => 1,\n        'b' => 2,\n    ];\n}"},
		{"array with static method call", nil, "<?php\n$foo = [\n    static::createNoErrorReport(),\n    1,\n];", "<?php\n$foo = [\n    static::createNoErrorReport(),\n    1,\n];"},
		{"ternary operator in property", nil, "<?php\nclass Foo\n{\n    public int $bar = BAZ ? -1 : 1;\n}", "<?php\nclass Foo\n{\n    public int $bar = BAZ ? -1 : 1;\n}"},
		{"multiline ternary operator in class constant", nil, "<?php\nclass Foo\n{\n    const BAR = BAZ\n        ? 1\n    : 2;\n}", "<?php\nclass Foo\n{\n    const BAR = BAZ\n        ? 1\n        : 2;\n}"},
		{"multiline nested ternary operator in class constant", nil, "<?php\nclass Foo\n{\n    const BAR = A\n    ? B\n        ? C\n            ? D\n            : E\n        : F\n    : G;\n}", "<?php\nclass Foo\n{\n    const BAR = A\n        ? B\n        ? C\n        ? D\n        : E\n        : F\n        : G;\n}"},
		{"multiline ternary operator in class constant with indentation to adjust", nil, "<?php\nclass Foo\n{\n    const BAR = A\n                ? B\n    : C;\n}", "<?php\nclass Foo\n{\n    const BAR = A\n        ? B\n        : C;\n}"},
		{"braceless if with return", nil, "<?php\nif (1 == 2)\n    return;\n\nif (1 == 2)\n    return false;", "<?php\nif (1 == 2)\n    return;\n\nif (1 == 2)\n    return false;"},
		{"functions \"set\" and \"get\" (like property hooks, but not)", nil, "<?php if ($x) {\n    set();\n} elseif ($y) {\n    SET();\n} else {\n    get();\n}", "<?php if ($x) {\n    set();\n} elseif ($y) {\n    SET();\n} else {\n    get();\n}"},
		{"with tabs", nil, "<?php\nif ($foo) {\n  foo();\n       bar();\n }", "<?php\nif ($foo) {\n\tfoo();\n\tbar();\n}"},
	}
	pass, fail := 0, 0
	for _, c := range cases {
		var f fixerRule = StatementIndentation{}
		if c.cfg != nil {
			f = StatementIndentation{}.WithConfig(c.cfg).(fixerRule)
		}
		got, _ := apply(t, f, c.input)
		switch {
		case got == c.expected:
			pass++
			if stmtIndentKnownFailures[c.name] {
				t.Errorf("%s now PASSES - remove it from stmtIndentKnownFailures", c.name)
			}
		case stmtIndentKnownFailures[c.name]:
			fail++
		default:
			fail++
			t.Errorf("%s:\n  in=%q\n got=%q\nwant=%q", c.name, c.input, got, c.expected)
		}
	}
	t.Logf("php-cs-fixer StatementIndentation cases: %d pass, %d fail of %d (%d known gaps)",
		pass, fail, pass+fail, len(stmtIndentKnownFailures))
}

var stmtIndentKnownFailures = map[string]bool{
	"use list":                              true, // multiline trait use (CT::T_USE_TRAIT) deeper indent not modelled
	"trait import with conflict resolution": true, // trait use with conflict block
	"with tabs":                             true, // harness cannot pass a tab WhitespacesFixerConfig
}
